 70	        uint8 quoteDecimals = 0;
 71	        try IERC20Metadata(quoteToken_).decimals() returns (uint8 decimals_) {
 72	            quoteDecimals = decimals_;
 73	        } catch {
 74	            revert UnsupportedQuoteToken(quoteToken_);
 75	        }
